/**
 * The release notes the Console ships (Round 16 WP07, SPEC S4).
 *
 * `release-notes.gen.json` is generated by `scripts/build_release_notes.py` from
 * `docs/releases/notes/<version>.json` and checked in under `webui/src` (the Docker Web
 * build stage cannot read `docs/`). It is imported only by lazy modules (the What's new
 * dialog and the Communication, What's new page), never by the entry chunk.
 *
 * The notes are trusted repository content, validated as plain text by the generator;
 * the Console still renders every string as a text node (`**bold**` and `` `code` `` are
 * drawn by {@link InlineText} as elements, never as markup).
 */
import rawNotes from './release-notes.gen.json';
import { navDest, NAV_ITEMS, navVisible, type PageId } from '../nav';

export type HighlightKind = 'new' | 'improved' | 'fixed' | 'removed' | 'security';
export type HighlightArea =
  | 'cases'
  | 'chat'
  | 'dashboards'
  | 'detection'
  | 'intelligence'
  | 'automation'
  | 'security'
  | 'administration'
  | 'platform'
  | 'help';

export interface NotesImage {
  /** Path under the Help Center bundle root (`assets/releases/0.2.0/x.webp`). */
  src: string;
  width: number;
  height: number;
}

export interface NotesScreenshot {
  light: NotesImage;
  dark: NotesImage | null;
  alt: string;
  caption: string | null;
}

export interface NotesHighlight {
  id: string;
  kind: HighlightKind;
  area: HighlightArea;
  title: string;
  summary: string;
  details: string[];
  featured: boolean;
  /** `resource:action` a viewer needs for this highlight to be offered in the dialog. */
  requires: string | null;
  /** The Console page "Open" goes to. */
  open: string | null;
  /** A Help Center path (`analyst/case-manager/#tabs`). */
  help: string | null;
  screenshot: NotesScreenshot | null;
}

export interface NotesUpdate {
  id: string;
  /** ISO date, or null for an update of a Testing release not yet released. */
  date: string | null;
  title: string;
  highlights: NotesHighlight[];
}

export interface NotesRecord {
  version: string;
  date: string;
  summary: string;
  docs: string;
}

export interface NotesRelease {
  version: string;
  status: 'released' | 'testing';
  date: string | null;
  title: string;
  summary: string;
  docs: string;
  updates: NotesUpdate[];
  records: NotesRecord[];
}

export interface ReleaseNotes {
  schema: number;
  latest: string;
  releases: NotesRelease[];
}

/** The notes bundled with this Console. */
export const RELEASE_NOTES = rawNotes as unknown as ReleaseNotes;

export const KIND_LABEL: Record<HighlightKind, string> = {
  new: 'New',
  improved: 'Improved',
  fixed: 'Fixed',
  removed: 'Removed',
  security: 'Security',
};

export const AREA_LABEL: Record<HighlightArea, string> = {
  cases: 'Cases',
  chat: 'Chat',
  dashboards: 'Dashboards',
  detection: 'Detection',
  intelligence: 'Intelligence',
  automation: 'Automation',
  security: 'Security',
  administration: 'Administration',
  platform: 'Platform',
  help: 'Help',
};

export type HasPermission = (resource: string, action: string) => boolean;

/** True when the viewer holds the grant a highlight names (or it names none). */
export function highlightUsable(highlight: NotesHighlight, has: HasPermission): boolean {
  if (!highlight.requires) return true;
  const [resource, action] = highlight.requires.split(':');
  return Boolean(resource && action) && has(resource, action);
}

/**
 * True when the navigation would offer `page` to this viewer: the same visibility rule
 * as the rail (the row, or the child that opens the page, must pass `navVisible`).
 */
export function pageOpenable(page: string | null, has: HasPermission): page is PageId {
  if (!page) return false;
  for (const item of NAV_ITEMS) {
    if (item.id === page && !(item.children ?? []).some((child) => navDest(child) === page)) {
      return navVisible(item, has);
    }
    const child = (item.children ?? []).find((candidate) => navDest(candidate) === page);
    if (child) return navVisible(item, has) && navVisible(child, has);
  }
  return false;
}

/** Every update, newest first, with the release it belongs to. */
export function allUpdates(notes: ReleaseNotes): { release: NotesRelease; update: NotesUpdate }[] {
  return notes.releases.flatMap((release) => release.updates.map((update) => ({ release, update })));
}

/** This browser's fallback marker, written only when saving the account marker failed. */
export const seenMirrorKey = (user?: string | null): string => `soc.whatsNew.seen:${user || 'default'}`;

/** This browser's fallback marker for `user`, or `null` (storage blocked or empty). */
export function readSeenMirror(user?: string | null): string | null {
  try {
    return window.localStorage.getItem(seenMirrorKey(user));
  } catch {
    return null;
  }
}

/**
 * Route keys that open one record: a deep link to a task (a case, a report, a
 * conversation, a rule, an audit record, a runbook). The welcome never covers one; it
 * waits until the person reaches a page that is not one.
 */
const RECORD_KEYS = ['caseId', 'reportId', 'conversationId', 'messageId', 'rule', 'record', 'id'] as const;

export function opensRecord(opts: Partial<Record<(typeof RECORD_KEYS)[number], unknown>> | undefined): boolean {
  return RECORD_KEYS.some((key) => Boolean(opts?.[key]));
}

/*
 * The marker a person had before the dialog moved it (this page view only). The dialog
 * writes the newest update id when it closes, and "See all changes" opens the
 * Communication, What's new page at the same moment, so the page would otherwise read the
 * new marker and mark nothing as new. The host records the old marker first; the page
 * reads it once as its baseline. Memory only: a reload starts from the stored marker.
 */
let markerBeforeClose: { value: string | null } | null = null;

export function rememberMarkerBeforeClose(value: unknown): void {
  markerBeforeClose = { value: typeof value === 'string' ? value : null };
}

/** The remembered marker, once; `undefined` when the dialog did not run this page view. */
export function takeMarkerBeforeClose(): string | null | undefined {
  const remembered = markerBeforeClose;
  markerBeforeClose = null;
  return remembered ? remembered.value : undefined;
}

const DATE_FORMAT = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });

/** `25 Nov 2026` for an ISO date (read as a calendar date, never shifted by a time zone). */
export function shortDate(value: string | null): string | null {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00Z`);
  return Number.isNaN(date.getTime()) ? null : DATE_FORMAT.format(date);
}
